const lesson = (level, summary, why, code, codeLabel, steps, pitfalls, takeaway, extras = {}) => ({
  level, summary, why, code, codeLabel, steps, pitfalls, takeaway, ...extras,
});

const LESSONS = {
  mvc: lesson("Fundamento", "MVC separa una petición web en datos y reglas, decisión de respuesta y presentación.", "Te permite recorrer una feature sin perderte: ruta → controller → modelo → vista.", "resources :posts, only: :index\n\nclass PostsController < ApplicationController\n  def index\n    @posts = Post.published.order(created_at: :desc)\n  end\nend\n\n# app/views/posts/index.html.erb\n<% @posts.each do |post| %>\n  <h2><%= post.title %></h2>\n<% end %>", "Una petición completa", ["La ruta convierte GET /posts en PostsController#index.", "El controller coordina y prepara @posts; la vista presenta y el modelo conoce persistencia y reglas.", "La separación es por responsabilidad, no por obligación de tener clases gigantes."], ["Un controller enorme suele contener lógica que debería vivir en un modelo, query o service object.", "MVC no impide crear objetos pequeños dentro de cada capa."], "Pensalo como una cadena de responsabilidades: cada pieza debe tener un motivo claro para existir."),
  coc: lesson("Fundamento", "Rails usa convenciones previsibles para conectar nombres, tablas, rutas y vistas automáticamente.", "Aprenderlas te permite leer una app Rails rápido y escribir mucho menos código repetitivo.", "class User < ApplicationRecord\nend\n\n# Rails espera por convención:\n# tabla: users\n# controller: UsersController\n# vista: app/views/users/show.html.erb\n# primary key: id", "Lo que Rails infiere", ["User se pluraliza como users para buscar la tabla.", "UsersController#show busca show.html.erb dentro de users.", "Podés romper una convención configurándola explícitamente, pero primero entendé el default."], ["No memorices magia aislada: preguntá qué convención conecta cada pieza.", "Cambiar nombres sin necesidad agrega configuración y superficie de error."], "En Rails, un buen nombre suele funcionar como configuración."),
  ar_pattern: lesson("Fundamento", "Active Record mezcla objeto de dominio y persistencia; Data Mapper mantiene esas responsabilidades separadas.", "La diferencia explica por qué Rails se siente directo y cuándo puede convenir una frontera adicional.", "post = Post.new(title: \"Hola\")\npost.save\n\n# Active Record: el objeto sabe persistirse.\n\npost = Post.new(title: \"Hola\")\npost_repository.save(post)\n\n# Data Mapper: un colaborador guarda el objeto.", "Dos límites de persistencia", ["Active Record es muy productivo para CRUD y asociaciones.", "Data Mapper puede aislar mejor un dominio complejo de detalles de SQL.", "La arquitectura debe responder a una necesidad real, no a una moda."], ["Un repository que solo repite User.find no agrega una frontera útil.", "Active Record no obliga a poner toda la lógica de negocio en el modelo."], "El patrón define dónde vive la persistencia; no es una competencia entre nombres."),
  ar_orm: lesson("Núcleo de Rails", "Active Record traduce métodos Ruby en consultas SQL encadenables y operaciones CRUD.", "Es el vocabulario diario para leer, crear, actualizar y borrar datos.", "posts = Post.where(published: true)\n                     .where(\"created_at > ?\", 30.days.ago)\n                     .order(created_at: :desc)\n\npost = Post.create!(title: \"Rails\", published: true)\npost.update!(title: \"Rails 8\")\npost.destroy!", "Consulta y mutaciones", ["where y order construyen una relación; la consulta suele ejecutarse cuando necesitás los resultados.", "create! y update! lanzan excepción si fallan; las versiones sin ! devuelven false.", "find(id) falla si no existe y find_by devuelve nil."], ["No materialices con to_a o each antes de terminar de construir la consulta.", "El ORM no reemplaza índices, restricciones ni un buen diseño de base."], "Identificá si estás manipulando una relación, un registro o resultados ya cargados."),
  assoc_belongs: lesson("Núcleo de Rails", "Las asociaciones expresan relaciones entre modelos y ocultan buena parte del manejo de claves foráneas.", "Un modelo bien asociado hace que el código de negocio lea como el dominio real.", "class Post < ApplicationRecord\n  has_many :comments, dependent: :destroy\nend\n\nclass Comment < ApplicationRecord\n  belongs_to :post\nend\n\npost.comments.create!(body: \"Muy claro\")\ncomment.post.title", "Uno a muchos", ["comments tiene post_id; por eso belongs_to vive en Comment.", "Post has_many :comments busca filas cuyo post_id coincide.", "dependent: :destroy es una decisión explícita de ciclo de vida."], ["belongs_to suele ser obligatorio en Rails moderno: confirmá si tu caso permite ausencia.", "La asociación y la integridad de la foreign key también necesitan una migración correcta."], "La ubicación de la foreign key te dice dónde va belongs_to."),
  assoc_through: lesson("Núcleo de Rails", "has_many :through modela muchos-a-muchos cuando la relación intermedia tiene datos o comportamiento propio.", "Es más expresivo que esconder una relación importante en una tabla de unión sin identidad.", "class Student < ApplicationRecord\n  has_many :enrollments\n  has_many :courses, through: :enrollments\nend\n\nclass Enrollment < ApplicationRecord\n  belongs_to :student\n  belongs_to :course\n  validates :status, presence: true\nend\n\nstudent.courses\nstudent.enrollments.active", "La relación intermedia importa", ["Enrollment conecta student_id con course_id.", "Student navega a courses y también puede consultar el estado de cada enrollment.", "La unión puede tener permisos, fechas, estado y validaciones."], ["Si la unión no tiene identidad ni atributos, una relación más simple podría bastar.", "Evitá duplicados con una restricción única cuando corresponda."], "Si la unión tiene una historia que contar, tratala como modelo."),
  n_plus_one: lesson("Performance", "N+1 ocurre cuando una consulta inicial trae N registros y luego se ejecuta otra por cada relación.", "Puede parecer correcto en desarrollo y volverse muy lento cuando crece la colección.", "Post.limit(100).each do |post|\n  puts post.author.name\nend\n\n# 1 query para posts + 1 query por cada author:\n# SELECT * FROM posts LIMIT 100\n# SELECT * FROM users WHERE id = 7\n# SELECT * FROM users WHERE id = 8", "Cómo aparece", ["post.author parece una propiedad, pero puede disparar una consulta si author no está cargado.", "Con 100 posts podés terminar con 101 queries.", "Medí con logs o Bullet antes de optimizar a ciegas."], ["No toda repetición es N+1: buscá una query por elemento.", "Eager loading indiscriminado también puede traer demasiados datos."], "Preguntá cuántas consultas produce cada loop que navega asociaciones."),
  eager_loading: lesson("Performance", "Eager loading carga asociaciones antes de usarlas para evitar consultas repetidas dentro de loops.", "Es la solución práctica al N+1, equilibrando consultas, memoria y tamaño del resultado.", "posts = Post.includes(:author).limit(100)\n\nposts.each do |post|\n  puts post.author.name\nend\n\n# preload: queries separadas\n# eager_load: LEFT OUTER JOIN cuando hace falta", "Cargar lo que vas a leer", ["includes permite traer author por adelantado.", "preload suele usar consultas separadas; eager_load puede armar un join.", "Si filtrás u ordenás por la tabla asociada, revisá qué estrategia usa Rails."], ["includes de una colección enorme puede gastar más memoria que el problema original.", "Mirá los logs: optimizar asociaciones también requiere medir."], "La optimización correcta depende de cantidad de queries, tamaño y memoria."),
  migrations: lesson("Núcleo de Rails", "Una migration describe un cambio versionado y reproducible sobre el esquema de la base.", "Permite que desarrollo, CI y producción apliquen la misma historia de cambios.", "class AddPublishedToPosts < ActiveRecord::Migration[7.1]\n  def change\n    add_column :posts, :published, :boolean, null: false, default: false\n    add_index :posts, :published\n  end\nend\n\n# rails db:migrate\n# rails db:rollback", "Cambio reversible", ["Rails registra qué migrations fueron aplicadas.", "change infiere cómo revertir operaciones simples.", "En tablas grandes, defaults, índices y backfills requieren pensar en locks y tiempo de deploy."], ["No edites una migration ya aplicada en producción: creá otra.", "Agregar la columna no siempre alcanza: datos existentes pueden necesitar backfill."], "Una migration es código de infraestructura con historia, no solo un ALTER TABLE."),
  validations: lesson("Núcleo de Rails", "Las validaciones protegen el modelo antes de persistirlo y explican por qué un registro es inválido.", "Centralizan reglas de datos y permiten devolver errores útiles al usuario.", "class Post < ApplicationRecord\n  validates :title, presence: true, length: { maximum: 100 }\n  validates :slug, uniqueness: true\nend\n\npost = Post.new(title: \"\")\npost.save # false\npost.errors.full_messages\n# [\"Title can't be blank\"]", "Validar antes de guardar", ["save y create ejecutan validaciones por default.", "errors contiene los motivos de rechazo.", "La unicidad también necesita un índice unique en la base para evitar carreras."], ["Una validación Ruby no reemplaza NOT NULL, foreign keys ni índices.", "La lógica de negocio compleja merece una interfaz más explícita."], "El modelo valida el estado; la base garantiza la integridad bajo concurrencia."),
  scopes: lesson("Núcleo de Rails", "Un scope es una consulta nombrada, reutilizable y encadenable sobre un modelo.", "Evita repetir filtros comunes y hace que la consulta exprese intención.", "class Post < ApplicationRecord\n  scope :published, -> { where(published: true) }\n  scope :recent, -> { order(created_at: :desc) }\nend\n\nPost.published.recent.limit(10)\nPost.where(author: user).published", "Consultas con intención", ["El scope devuelve una relación, por eso puede combinarse con where, order y limit.", "No debería tener efectos secundarios.", "Si crece con joins y muchos parámetros, extraelo a un Query Object."], ["Un scope gigante oculta demasiadas decisiones.", "Cuidado con scopes que devuelven nil y rompen el encadenamiento."], "Un buen scope tiene un nombre de negocio y una consulta corta."),
  sti: lesson("Diseño de modelos", "STI guarda varios subtipos en una tabla y usa una columna type para reconstruir la clase Ruby.", "Sirve cuando los subtipos son variantes del mismo concepto y comparten la mayoría del esquema.", "class Vehicle < ApplicationRecord\nend\n\nclass Car < Vehicle\nend\n\nclass Motorcycle < Vehicle\nend\n\nCar.create!(brand: \"Ford\")\nVehicle.all # todos los tipos\nCar.all     # WHERE type = \"Car\"", "Una tabla, varias clases", ["vehicles tiene type y columnas compartidas.", "Rails instancia Car al leer una fila con type = Car.", "Vehicle.all incluye todos los subtipos; Car.all filtra automáticamente."], ["type tiene significado especial en Active Record.", "STI se vuelve incómodo cuando los subtipos divergen demasiado."], "STI modela una familia homogénea, no cualquier conjunto de clases relacionadas."),
  sti_tradeoffs: lesson("Diseño de modelos", "STI simplifica consultas, pero concentra atributos de todos los subtipos en una tabla.", "Elegirlo es un trade-off de evolución del dominio, no solo una decisión de sintaxis.", "vehicles\n# id | type       | wheels | battery_capacity | cargo_volume\n# 1  | Car        | 4      | NULL             | NULL\n# 2  | Motorcycle  | 2      | NULL             | NULL\n# 3  | ElectricCar | 4      | 75               | NULL\n\n# Muchos NULL y validaciones condicionales\n# pueden indicar que STI ya no encaja.", "El costo de compartir tabla", ["La ventaja es consultar toda la familia sin joins entre tablas.", "El costo son columnas que no aplican a todos, reglas condicionales y migraciones acopladas.", "Alternativas: tablas separadas, composición o un modelo base más pequeño."], ["No decidas por cantidad de clases, sino por cuánto comparten datos y comportamiento.", "Muchos if self.type suelen señalar una abstracción deteriorada."], "La pregunta clave es si los subtipos van a evolucionar juntos."),
  polymorphic: lesson("Diseño de modelos", "Una asociación polimórfica permite que un registro apunte a modelos de distintos tipos usando id y type.", "Sirve para comportamientos transversales como comentarios, adjuntos, likes o auditorías.", "class Comment < ApplicationRecord\n  belongs_to :commentable, polymorphic: true\nend\n\nclass Post < ApplicationRecord\n  has_many :comments, as: :commentable\nend\n\nclass Video < ApplicationRecord\n  has_many :comments, as: :commentable\nend\n\npost.comments.create!(body: \"Buen post\")\nvideo.comments.create!(body: \"Buen video\")", "Un comentario para varios modelos", ["comments guarda commentable_id y commentable_type.", "Comment puede navegar commentable sin conocer el tipo concreto.", "Cada modelo dueño debe declarar has_many ... as: :commentable."], ["Las foreign keys tradicionales no validan fácilmente ambos tipos.", "No uses polimorfismo si una relación explícita sería más clara."], "Polimorfismo conecta conceptos distintos; STI representa variantes de uno mismo."),
  sprockets: lesson("Legacy y assets", "Sprockets es el asset pipeline clásico para organizar, concatenar, minificar y servir CSS y JavaScript.", "Muchas apps existentes lo usan; entenderlo evita tratar su estructura como una caja negra.", "// app/assets/javascripts/application.js\n//= require jquery\n//= require_tree .\n\n/* app/assets/stylesheets/application.css */\n/*\n *= require_self\n *= require_tree .\n */\n\n// rails assets:precompile", "Manifest clásico", ["El manifest declara qué archivos entran en el bundle final.", "El deploy precompila assets listos para servir.", "Fingerprinting permite cachear el resultado sin servir contenido viejo."], ["Sprockets no es un bundler moderno de módulos JavaScript como Webpack.", "En una app nueva, identificá si usa Sprockets, import maps o un bundler."], "Sprockets es packaging de assets, no el framework de UI."),
  webpacker: lesson("Legacy y assets", "Webpacker fue la integración oficial de Webpack y npm dentro de Rails.", "Aparece en Rails 5/6 y explica estructuras con packs, yarn y app/javascript.", "// app/javascript/packs/application.js\nimport React from \"react\"\nimport { createRoot } from \"react-dom/client\"\nimport App from \"../components/App\"\n\ncreateRoot(document.getElementById(\"root\"))\n  .render(<App />)\n\n// <%= javascript_pack_tag \"application\" %>", "JavaScript con packs", ["Webpack resuelve imports, transforma sintaxis y genera bundles.", "Webpacker conectaba ese proceso con helpers Rails y deploy.", "Su flexibilidad trajo configuración y complejidad operativa."], ["No confundas Webpacker con Webpack: uno integra al otro en Rails.", "En proyectos actuales revisá si fue migrado a jsbundling-rails o import maps."], "Es contexto histórico útil para mantener apps, no siempre la elección actual."),
  jsbundling: lesson("Legacy y assets", "jsbundling-rails conecta Rails con esbuild, Bun, Webpack o Rollup para compilar JavaScript moderno.", "Permite usar módulos, TypeScript o React manteniendo Rails como backend y servidor.", "gem \"jsbundling-rails\"\n\n# rails javascript:install:esbuild\n\n// app/javascript/application.js\nimport \"./controllers\"\nimport { formatPrice } from \"./money\"\n\nconsole.log(formatPrice(1200))", "Bundler moderno como proceso separado", ["Rails sirve los archivos finales producidos por el bundler.", "El script de build debe ejecutarse en desarrollo y deploy.", "Para JavaScript simple, import maps puede evitar un bundler completo."], ["Una build que funciona localmente pero falla en deploy suele tener un script faltante.", "Elegí la herramienta por necesidades reales, no por inercia."], "La decisión importante es quién compila JavaScript y cuándo."),
  fingerprint: lesson("Legacy y assets", "Fingerprinting agrega un hash al nombre del archivo para que el navegador pueda cachearlo sin servir una versión vieja.", "Es la base del cache busting confiable en assets estáticos.", "application.js\n\n# compilado:\napplication-a1b2c3d4.js\n\n# después de un cambio:\napplication-f9e8d7c6.js", "El nombre representa el contenido", ["El hash cambia cuando cambia el archivo.", "El navegador puede conservar la URL durante mucho tiempo porque una versión nueva tiene otra URL.", "Los helpers Rails generan la URL correcta desde el manifest."], ["No hardcodees nombres compilados si Rails tiene helpers.", "CDN y manifest deben invalidarse o actualizarse correctamente durante el deploy."], "Cambiar la URL cuando cambia el contenido permite cache largo y deploys frecuentes."),
  api_mode: lesson("Arquitectura", "Rails API-only elimina las vistas tradicionales y se enfoca en endpoints JSON para otro cliente.", "Es común cuando React, mobile u otro servicio consume Rails como backend.", "rails new learning_api --api\n\nclass PostsController < ActionController::API\n  def show\n    post = Post.find(params[:id])\n    render json: post, status: :ok\n  end\nend\n\n# GET /posts/42 -> { \"id\": 42, \"title\": \"Rails\" }", "Backend JSON", ["El cliente hace HTTP y recibe datos serializados.", "El controller define contrato, status y errores.", "Autenticación, CORS, versionado y serialización pasan a ser decisiones explícitas."], ["API-only no significa REST perfecto ni seguridad resuelta.", "No expongas el modelo completo sin revisar campos sensibles."], "En API-only, el contrato HTTP es la interfaz principal."),
  service_object: lesson("Diseño de aplicación", "Un Service Object encapsula un caso de uso: una acción que coordina varios pasos y objetos.", "Evita controllers gordos y hace testeable un flujo como cobrar una orden y enviar una notificación.", "class CheckoutOrder\n  def initialize(cart:, payment_gateway:, mailer:)\n    @cart, @payment_gateway, @mailer = cart, payment_gateway, mailer\n  end\n\n  def call\n    order = Order.create!(total: @cart.total)\n    @payment_gateway.charge(order.total)\n    @mailer.order_created(order).deliver_later\n    order\n  end\nend\n\nCheckoutOrder.new(cart:, payment_gateway:, mailer:).call", "Un caso de uso explícito", ["El service recibe dependencias y datos de entrada.", "call coordina; las reglas simples siguen en sus objetos dueños.", "Las dependencias inyectadas se pueden reemplazar en tests."], ["No conviertas todo método en service por reflejo.", "Definí qué devuelve call y cómo representa errores y transacciones."], "Un service representa una intención del negocio, no una carpeta para código perdido."),
  form_object: lesson("Diseño de aplicación", "Un Form Object concentra campos y validaciones de un formulario que puede tocar varios modelos.", "Evita llenar User, Profile o controllers con reglas que solo aplican a una pantalla.", "class SignupForm\n  include ActiveModel::Model\n  attr_accessor :email, :name, :company_name\n\n  validates :email, presence: true\n  validates :company_name, presence: true\n\n  def save\n    return false unless valid?\n    User.create!(email: email, name: name)\n    Company.create!(name: company_name)\n  end\nend", "Un formulario con varios destinos", ["ActiveModel ofrece valid?, errors y atributos.", "El objeto valida la combinación de campos del formulario.", "Si hay varios writes, save debería ser atómico con una transacción."], ["No lo uses para reemplazar un modelo de dominio con identidad propia.", "Asegurá que no quede una parte guardada si otra falla."], "El Form Object modela el flujo de entrada, no necesariamente una tabla."),
  query_object: lesson("Diseño de aplicación", "Un Query Object encapsula una consulta compleja con nombre, parámetros y tests propios.", "Mantiene controllers y scopes legibles cuando aparecen joins, filtros y reglas.", "class AvailableCourses\n  def self.call(student:, term:)\n    Course.joins(:enrollments)\n      .where(enrollments: { student: student, status: \"active\" })\n      .where(\"courses.title ILIKE ?\", \"%#{term}%\")\n      .distinct\n  end\nend\n\nAvailableCourses.call(student:, term: \"ruby\")", "Consulta con intención", ["Devuelve una relación para que el caller todavía pueda paginar u ordenar.", "La clase se prueba con datos y casos límite sin levantar un controller.", "El nombre explica la intención, no el detalle SQL."], ["No escondas mutaciones en un objeto llamado Query.", "Controlá interpolación y performance usando condiciones seguras."], "Una query compleja merece una interfaz que se pueda nombrar y medir."),
  decorator: lesson("Diseño de aplicación", "Un Decorator o Presenter agrega comportamiento de presentación sin contaminar el modelo de dominio.", "Formatear fechas, precios o textos para UI no debería convertir al modelo en una bolsa de helpers visuales.", "class PostPresenter\n  def initialize(post)\n    @post = post\n  end\n\n  def published_label\n    @post.published? ? \"Publicado\" : \"Borrador\"\n  end\n\n  def formatted_date\n    I18n.l(@post.created_at.to_date)\n  end\nend\n\npresenter = PostPresenter.new(post)", "Presentación separada", ["El presenter envuelve al objeto y delega los datos de dominio.", "Sus métodos devuelven valores pensados para una vista o respuesta.", "Reglas de precios, permisos o invariantes siguen siendo dominio."], ["No hagas queries ocultas en cada método.", "No uses decoración para evitar modelar un concepto real del dominio."], "La presentación transforma; el dominio decide."),
  concern: lesson("Diseño de aplicación", "Un Concern empaqueta comportamiento compartido para incluirlo en varios modelos o controllers.", "Puede reducir repetición cuando la capacidad es pequeña, coherente y transversal.", "module Publishable\n  extend ActiveSupport::Concern\n\n  included do\n    scope :published, -> { where(published: true) }\n  end\n\n  def publish!\n    update!(published: true, published_at: Time.current)\n  end\nend\n\nclass Post < ApplicationRecord\n  include Publishable\nend", "Comportamiento compartido", ["ActiveSupport::Concern organiza métodos y hooks compartidos.", "El modelo obtiene una interfaz clara como publish!.", "La abstracción funciona cuando nombra una capacidad real."], ["Muchos concerns pueden ocultar de dónde vienen métodos y callbacks.", "Si se comparten pocas líneas, duplicar puede ser más claro."], "Un Concern debe nombrar una capacidad, no ser un cajón de utilidades."),
  callbacks: lesson("Diseño de aplicación", "Los callbacks ejecutan código alrededor del ciclo de vida de un registro.", "Son útiles para efectos ligados a persistencia, pero pueden ocultar consecuencias importantes.", "class User < ApplicationRecord\n  after_commit :enqueue_welcome_email, on: :create\n\n  private\n\n  def enqueue_welcome_email\n    WelcomeEmailJob.perform_later(id)\n  end\nend", "Efecto posterior al commit", ["after_commit corre cuando la transacción quedó confirmada.", "Enviar un job después del commit evita notificar un registro que hizo rollback.", "El callback se dispara desde cualquier lugar que cree User."], ["Evita callbacks para flujos largos o sorprendentes.", "before_save ocurre antes de persistir definitivamente; after_commit ocurre después."], "Cuanto más importante sea el flujo, más explícito conviene hacerlo con service o job."),
  repository: lesson("Diseño de aplicación", "Un Repository ofrece una frontera estable para leer y guardar objetos cuando no querés exponer la persistencia directamente.", "Puede ayudar con varias fuentes de datos o un dominio que necesita aislarse de Active Record.", "class UserRepository\n  def find_active(id)\n    User.where(active: true).find(id)\n  end\n\n  def save(user)\n    user.save!\n  end\nend\n\nuser = UserRepository.new.find_active(42)", "Una frontera de datos", ["El caller conoce una interfaz de búsqueda, no la consulta concreta.", "El repository puede combinar Active Record, una API o una cache.", "En Rails puro, Active Record ya cubre mucho de este rol."], ["Un repository que solo repite User.find no agrega valor.", "No escondas relaciones encadenables si el caller necesita componer consultas."], "Repository es una decisión de límite arquitectónico, no un requisito de Rails."),
  di: lesson("Diseño de aplicación", "Dependency Injection pasa colaboradores desde afuera para que una clase no quede acoplada a implementaciones concretas.", "Facilita cambiar proveedores y probar sin hacer requests o pagos reales.", "class NotifyOrder\n  def initialize(mailer: OrderMailer, clock: Time)\n    @mailer, @clock = mailer, clock\n  end\n\n  def call(order)\n    @mailer.confirmation(order, sent_at: @clock.current).deliver_now\n  end\nend\n\n# Test: mailer: fake_mailer, clock: frozen_clock", "Colaboradores reemplazables", ["La clase declara qué necesita en initialize.", "Producción usa implementaciones reales; el test pasa fakes.", "La inyección manual suele ser suficiente: no hace falta un contenedor complejo."], ["Inyectar todo por reflejo puede hacer la clase ilegible.", "DI es diseño de dependencias; mocks son solo una técnica de test."], "Si una dependencia puede variar o tiene efectos externos, hacerla visible ayuda."),
  srp: lesson("Diseño de aplicación", "Single Responsibility pide que una clase tenga una razón principal para cambiar.", "Una responsabilidad clara reduce el radio de impacto y facilita testear modificaciones.", "class OrdersController < ApplicationController\n  def create\n    CheckoutOrder.new(...).call\n  end\nend\n\n# Controller: HTTP\n# CheckoutOrder: caso de uso\n# PaymentGateway: integración de pago\n# OrderMailer: notificación", "Separar motivos de cambio", ["Preguntá qué cosas distintas podrían pedir cambios en una clase.", "Extraé una colaboración cuando mejora el lenguaje y los tests.", "SRP no significa tener una clase de cinco líneas por cada operación."], ["No confundas responsabilidad con cantidad de métodos.", "Repartir código sin una interfaz clara solo distribuye la complejidad."], "Una clase cohesionada cuenta una historia corta y estable."),
  open_closed: lesson("Diseño de aplicación", "Open/Closed propone extender comportamiento con nuevas variantes sin reescribir todos los consumidores.", "Reduce cambios frágiles cuando el sistema incorpora tipos o estrategias nuevas.", "class ShippingPrice\n  def initialize(strategy)\n    @strategy = strategy\n  end\n\n  def call(order)\n    @strategy.price_for(order)\n  end\nend\n\nclass FreeShipping\n  def price_for(_order) = 0\nend\n\nclass ExpressShipping\n  def price_for(order) = order.weight * 2.5\nend", "Extender con estrategias", ["El consumidor depende de una interfaz pequeña: price_for.", "Agregar FreeShipping no obliga a modificar ShippingPrice.", "La extensión puede usar composición o polimorfismo."], ["No diseñes una jerarquía abstracta antes de tener una variación real.", "Cerrado a modificación significa reducir cambios frágiles, no no tocar nunca el código."], "Buscá el punto de variación real y aislalo detrás de una interfaz pequeña."),
  rspec_basics: lesson("Testing", "RSpec organiza ejemplos con describe, context, it y expect para convertir comportamiento en documentación ejecutable.", "Una spec clara explica qué promete el código y protege futuras refactorizaciones.", "RSpec.describe Post, type: :model do\n  describe \"#published?\" do\n    context \"when published_at exists\" do\n      it \"returns true\" do\n        post = build(:post, published_at: Time.current)\n        expect(post).to be_published\n      end\n    end\n  end\nend", "Un ejemplo que explica comportamiento", ["describe agrupa el sujeto y context explica una condición.", "it define un resultado observable.", "expect afirma el resultado con un matcher."], ["No pruebes implementación interna si podés probar comportamiento.", "Muchos expects y setup suelen indicar más de un escenario mezclado."], "Una buena spec se lee como una frase: bajo esta condición, espero este comportamiento."),
  factory_bot: lesson("Testing", "FactoryBot crea objetos de prueba con defaults expresivos, asociaciones y traits reutilizables.", "Reduce setup repetido sin convertir cada spec en una lista frágil de atributos.", "FactoryBot.define do\n  factory :post do\n    title { \"Un post de prueba\" }\n    published { false }\n\n    trait :published do\n      published { true }\n    end\n  end\nend\n\nbuild(:post)              # memoria\ncreate(:post, :published) # base de test", "Datos de prueba con intención", ["build no persiste; create guarda en la base de test.", "Traits nombran estados que aparecen en varios escenarios.", "La spec todavía debería dejar claro qué datos necesita."], ["Factories con muchas asociaciones implícitas pueden volver lento el suite.", "Usá build o attributes_for cuando no necesitás persistencia."], "Una factory es un default cómodo, no una explicación automática del escenario."),
  spec_types: lesson("Testing", "Model, request y system specs observan capas distintas de una aplicación.", "Elegir la capa correcta hace los tests más rápidos y ubica mejor una falla.", "RSpec.describe Post, type: :model do\n  it { is_expected.to validate_presence_of(:title) }\nend\n\nRSpec.describe \"Posts API\", type: :request do\n  it \"returns posts\" do\n    get \"/posts\"\n    expect(response).to have_http_status(:ok)\n  end\nend", "La capa determina el alcance", ["Model specs enfocan reglas y comportamiento del modelo.", "Request specs recorren routing, controller, serialización y status HTTP.", "System specs simulan al usuario en el navegador y cubren integración amplia."], ["No pruebes todo como system spec: es lento y diagnostica peor.", "No te quedes solo con unit tests si el contrato HTTP es importante."], "Usá la prueba más pequeña que observe el comportamiento que te importa."),
  rack: lesson("Infraestructura", "Rack define una interfaz simple entre un servidor web y una aplicación Ruby.", "Te permite entender qué ocurre antes de Rails y cómo se agrega middleware.", "class TimingMiddleware\n  def initialize(app)\n    @app = app\n  end\n\n  def call(env)\n    started = Process.clock_gettime(Process::CLOCK_MONOTONIC)\n    status, headers, body = @app.call(env)\n    headers[\"X-Response-Time\"] = \"measured\"\n    [status, headers, body]\n  end\nend", "Un middleware envuelve la app", ["Una Rack app recibe env y devuelve [status, headers, body].", "Un middleware puede ejecutar lógica antes y después de delegar a @app.", "Rails usa un stack para cookies, sesiones, logs y seguridad."], ["El body de Rack es enumerable, no necesariamente un String.", "El orden de los middlewares importa porque cada capa envuelve a la siguiente."], "Middleware es una cadena de envoltorios alrededor de la aplicación."),
  gemfile: lesson("Infraestructura", "Gemfile declara dependencias y Bundler resuelve un conjunto reproducible registrado en Gemfile.lock.", "El lockfile evita combinaciones incompatibles entre desarrollo, CI y producción.", "source \"https://rubygems.org\"\n\ngem \"rails\"\ngem \"pg\"\n\ngroup :development, :test do\n  gem \"rspec-rails\"\n  gem \"factory_bot_rails\"\nend\n\n# bundle install\n# bundle exec rspec", "Dependencias por entorno", ["Gemfile expresa lo que necesita el proyecto.", "Bundler resuelve versiones transitivas y las fija en Gemfile.lock.", "Los grupos separan herramientas de desarrollo/test de runtime."], ["No borres el lockfile sin entender el impacto de resolver todo de nuevo.", "bundle exec asegura que el comando use las gems del bundle."], "Gemfile declara la intención; Gemfile.lock fija el resultado."),
  logger: lesson("Infraestructura", "Rails.logger registra eventos para entender qué ocurre en desarrollo, CI y producción.", "Los logs permiten reconstruir una falla sin llenar el código de puts.", "Rails.logger.info(\"checkout_started\", order_id: order.id)\nRails.logger.warn(\"payment_retry\", attempt: attempt)\n\nbegin\n  gateway.charge!\nrescue PaymentError => error\n  Rails.logger.error(\"payment_failed\", error: error.class.name)\n  raise\nend", "Loguear contexto útil", ["Elegí el nivel según severidad: debug, info, warn o error.", "Incluí IDs y contexto operacional, nunca secretos.", "Un log útil responde qué pasó, con qué entidad y en qué etapa."], ["No loguees passwords, tokens, tarjetas ni payloads completos.", "Mucho ruido hace que los eventos importantes sean imposibles de encontrar."], "Loguear no es imprimir: es dejar evidencia operable de un evento."),
  env_vars: lesson("Infraestructura", "Credentials y variables de entorno mantienen secretos y configuración fuera del código fuente.", "La misma app necesita valores distintos en desarrollo, CI y producción.", "DATABASE_URL=postgres://localhost/learning\n\nurl = ENV.fetch(\"DATABASE_URL\")\nsecret = Rails.application.credentials.dig(:stripe, :secret_key)\n\n# Nunca:\nSTRIPE_SECRET = \"sk_live_...\" # no commitear", "Configurar sin exponer secretos", ["ENV.fetch falla temprano si falta una variable obligatoria.", "credentials guarda valores cifrados y requiere administrar bien su key.", "Documentá nombres esperados sin publicar valores reales."], ["No pongas secretos en Git, logs, bundles frontend ni errores.", "Un valor del servidor no debe exponerse automáticamente al navegador."], "Configuración externa al código sigue necesitando validación y control de acceso."),
  routing_rest: lesson("Rails core", "El router traduce una combinación de verbo HTTP y path en una acción de controller.", "En una entrevista, diseñar una feature normalmente empieza por definir recursos, acciones y límites HTTP.", "Rails.application.routes.draw do\n  resources :orders, only: %i[index show create] do\n    member { post :cancel }\n  end\nend\n\n# GET  /orders      -> orders#index\n# POST /orders      -> orders#create\n# POST /orders/:id/cancel -> orders#cancel", "Diseñar la interfaz HTTP", ["resources genera rutas RESTful y helpers como orders_path.", "Usá verbos y status HTTP coherentes: GET lee, POST crea o dispara una acción, PATCH actualiza y DELETE elimina.", "Una acción no-CRUD como cancel puede ser member porque opera sobre una orden concreta."], ["No conviertas cada método interno en un endpoint.", "Rutas profundamente anidadas aumentan acoplamiento y URLs difíciles de mantener."], "Primero modelá el recurso y el contrato HTTP; después escribí el controller."),
  controllers_params: lesson("Rails core", "El controller recibe HTTP, autoriza y valida la forma de la entrada, delega el caso de uso y construye la respuesta.", "Strong Parameters evita mass assignment de campos que el cliente no debería controlar.", "class OrdersController < ApplicationController\n  def create\n    order = CheckoutOrder.new(user: current_user, params: order_params).call\n    redirect_to order_path(order), notice: \"Order created\"\n  end\n\n  private\n\n  def order_params\n    params.require(:order).permit(:address_id, items: %i[product_id quantity])\n  end\nend", "Controller delgado", ["params.require exige una raíz y permit crea una lista explícita de campos aceptados.", "El controller se ocupa de HTTP y delega la coordinación a un objeto con nombre.", "Autenticación y autorización deben ocurrir antes de ejecutar la acción."], ["Strong params valida forma y permisos de asignación, no reemplaza validaciones de dominio.", "Un controller que abre transacciones, cobra y envía emails está mezclando responsabilidades."], "Controller: traducir HTTP hacia el caso de uso y traducir su resultado de vuelta a HTTP."),
  responses_errors: lesson("Rails core", "Una acción Rails debe responder con representación, redirección o status coherente y mapear fallas esperables.", "El entrevistador puede evaluar tanto el happy path como qué ocurre con datos inválidos, ausencia o conflictos.", "def create\n  order = CheckoutOrder.new(user: current_user, params: order_params).call\n  render json: OrderSerializer.new(order), status: :created\nrescue ActiveRecord::RecordInvalid => error\n  render json: { errors: error.record.errors.full_messages }, status: :unprocessable_entity\nrescue ActiveRecord::RecordNotFound\n  head :not_found\nend", "Contrato de éxito y error", ["201 Created comunica creación; 422 comunica entrada válida como HTTP pero inválida para el dominio.", "render devuelve contenido; redirect_to indica al cliente que haga otra request.", "Errores inesperados se registran y normalmente se dejan llegar al handler global."], ["No rescates Exception ni devuelvas 200 para toda falla.", "No expongas stack traces ni detalles internos en una API."], "Un endpoint bien diseñado especifica entrada, salida, status y fallas previsibles."),
  transactions: lesson("Active Record", "Una transacción agrupa escrituras para que se confirmen todas o ninguna.", "Es imprescindible cuando una necesidad de negocio modifica varias filas que deben permanecer consistentes.", "order = Order.transaction do\n  order = user.orders.create!(status: \"pending\")\n  params[:items].each do |item|\n    order.items.create!(item)\n  end\n  order\nend\n\n# Cualquier excepción dentro del bloque provoca rollback.", "Mantener una invariante", ["Usá métodos con ! cuando una falla debe abortar toda la operación.", "La transacción protege cambios de base de datos, no puede deshacer un email o un request HTTP externo.", "Los efectos externos conviene ejecutarlos después del commit o mediante un job."], ["No mantengas una transacción abierta mientras esperás una API externa.", "Un rollback no revierte automáticamente lo que ya ocurrió en Stripe, Redis o un mailer."], "Transacción para consistencia local; idempotencia y compensación para efectos externos."),
  case_checkout: lesson("Caso de diseño", "Diseñar checkout exige separar HTTP, consistencia de datos, pago externo y efectos asíncronos.", "Es un excelente ejercicio de entrevista porque revela límites, transacciones, dependencias y manejo de fallas.", "class CheckoutOrder\n  def initialize(user:, cart:, payments:)\n    @user, @cart, @payments = user, cart, payments\n  end\n\n  def call\n    order = persist_order!\n    @payments.charge!(order)\n    OrderPaidJob.perform_later(order.id)\n    order\n  end\nend", "Esqueleto del caso de uso", ["OrdersController valida HTTP y llama a CheckoutOrder.", "El service crea Order e Items dentro de una transacción.", "PaymentGateway es una dependencia explícita; el job procesa email o tareas lentas después."], ["Cobrar dentro de una transacción larga puede retener locks; explicá idempotency keys y estados pending/paid/failed.", "Si el pago funciona y guardar el estado falla, necesitás retry o compensación: una transacción SQL no cruza sistemas."], "En diseño de negocio, nombrá invariantes, fronteras transaccionales, fallas parciales e idempotencia.", { prompt: "“Diseñá la creación de una orden que guarda sus items, cobra con un proveedor externo y envía confirmación.”", diagramTitle: "Arquitectura propuesta", diagram: [{ label: "POST /orders", detail: "Entrada HTTP" }, { label: "OrdersController", detail: "params + auth" }, { label: "CheckoutOrder", detail: "orquesta el caso" }, { label: "DB transaction", detail: "Order + Items" }, { label: "Payment adapter", detail: "proveedor externo" }, { label: "Active Job", detail: "email y efectos" }] }),
  case_reporting: lesson("Caso de diseño", "Un reporte filtrable debe mantener el controller pequeño y construir una Relation eficiente que pueda paginarse.", "Con tu experiencia en tablas grandes, este caso conecta frontend, API, SQL, índices y N+1.", "class OrdersReportQuery\n  def self.call(scope: Order.all, filters:)\n    scope\n      .includes(:customer)\n      .where(status: filters[:status])\n      .where(created_at: filters[:from]..filters[:to])\n      .order(created_at: :desc)\n  end\nend\n\nOrdersReportQuery.call(filters: params).page(params[:page])", "Query reutilizable y medible", ["El controller traduce filtros y pasa un scope inicial autorizado.", "El Query Object compone una Relation sin cargarla antes de paginar.", "Índices deben corresponder a filtros y orden frecuentes; includes evita N+1 al serializar customers."], ["No devuelvas 100k filas al navegador si podés paginar o generar una exportación asíncrona.", "Un índice acelera lecturas pero cuesta almacenamiento y escrituras; justificá columnas y orden."], "Para reportes: contrato de filtros, query componible, índices medidos, paginación y exportación aparte.", { prompt: "“Diseñá un endpoint de reportes con filtros, orden, datos relacionados y posible exportación masiva.”", diagramTitle: "Flujo de consulta", diagram: [{ label: "GET /reports", detail: "filtros + página" }, { label: "ReportsController", detail: "normaliza entrada" }, { label: "ReportQuery", detail: "compone Relation" }, { label: "SQL + índices", detail: "filtra y ordena" }, { label: "includes", detail: "evita N+1" }, { label: "Serializer", detail: "JSON paginado" }] }),
  case_signup: lesson("Caso de diseño", "Un registro que crea User, Profile y preferencias no mapea limpiamente a un único modelo.", "Permite explicar Form Object, validaciones cruzadas, transacción y efectos posteriores.", "class SignupForm\n  include ActiveModel::Model\n\n  def save\n    return false unless valid?\n    User.transaction do\n      user = User.create!(email:, password:)\n      user.create_profile!(name:, timezone:)\n      WelcomeJob.perform_later(user.id)\n      user\n    end\n  end\nend", "Formulario multi-modelo", ["El Form Object expone atributos y errors como un modelo sin representar una tabla.", "La transacción preserva la regla: no existe User sin Profile.", "La bienvenida se agenda después de persistir; para robustez se puede usar after_commit u outbox."], ["No metas reglas exclusivas del signup en User si no aplican a otros flujos.", "Asegurá qué ocurre si el job se agenda antes de que el commit sea visible."], "Modelá el flujo de entrada cuando su unidad conceptual es el caso de uso, no una fila.", { prompt: "“Un formulario debe crear usuario, perfil y preferencias, mostrando todos los errores juntos.”", diagramTitle: "Unidad de trabajo", diagram: [{ label: "POST /signup", detail: "varios campos" }, { label: "SignupForm", detail: "valida conjunto" }, { label: "DB transaction", detail: "todo o nada" }, { label: "User", detail: "identidad" }, { label: "Profile", detail: "datos asociados" }, { label: "WelcomeJob", detail: "efecto posterior" }] }),
  jobs_mailers: lesson("Diseño aplicado", "Active Job ejecuta trabajo fuera de la request y Action Mailer construye emails usando convenciones parecidas a controllers y vistas.", "Enviar correos o procesar exportaciones en línea aumenta latencia y fragilidad del endpoint.", "class OrderPaidJob < ApplicationJob\n  queue_as :default\n\n  def perform(order_id)\n    order = Order.find(order_id)\n    OrderMailer.confirmation(order).deliver_now\n  end\nend\n\nOrderPaidJob.perform_later(order.id)", "Mover efectos lentos fuera de HTTP", ["Pasá IDs simples al job y recargá el registro al ejecutarlo.", "Los jobs deben tolerar retry; diseñá operaciones idempotentes.", "Active Job es la API; Sidekiq u otro adapter puede ser el backend de ejecución."], ["perform_later no garantiza exactamente una ejecución.", "El registro puede haber cambiado o desaparecido cuando el job corra."], "Asíncrono mejora la request, pero obliga a pensar retries, idempotencia y observabilidad."),
  strategy_pattern: lesson("Patrón de diseño", "Strategy encapsula algoritmos intercambiables detrás de la misma interfaz.", "Es útil cuando una regla cambia por plan, país, método de envío o tipo de cliente sin llenar el service de condicionales.", "class ShippingCalculator\n  def initialize(strategy:)\n    @strategy = strategy\n  end\n\n  def call(order)\n    @strategy.price_for(order)\n  end\nend\n\nclass ExpressShipping\n  def price_for(order) = order.weight * 2.5\nend", "Variación explícita", ["El contexto depende de price_for, no de una clase concreta.", "Cada estrategia contiene una variante y puede probarse en aislamiento.", "La selección de estrategia puede ocurrir en un factory simple según datos del pedido."], ["Tres clases para una condición estable puede ser sobreingeniería.", "La interfaz debe ser pequeña y semánticamente consistente."], "Extraé Strategy cuando la variación es real, crece y cambia independientemente.", { prompt: "“El costo de envío cambia según standard, express o pickup y aparecerán más modalidades.”", diagramTitle: "Punto de variación", diagram: [{ label: "Checkout", detail: "necesita precio" }, { label: "ShippingCalculator", detail: "interfaz estable" }, { label: "Strategy", detail: "selección" }, { label: "Standard / Express / Pickup", detail: "algoritmos separados" }] }),
  adapter_pattern: lesson("Patrón de diseño", "Adapter traduce la API de un proveedor externo a una interfaz propia de la aplicación.", "Evita que Stripe, Salesforce o cualquier SDK contamine el caso de uso y facilita reemplazos y tests.", "class StripePaymentAdapter\n  def initialize(client: Stripe::PaymentIntent)\n    @client = client\n  end\n\n  def charge!(order)\n    @client.create(amount: order.total_cents, currency: \"usd\")\n  end\nend\n\nCheckoutOrder.new(payments: StripePaymentAdapter.new).call", "Aislar una integración", ["La aplicación define qué necesita: charge!, refund! o status.", "El adapter convierte nombres, formatos, errores y respuestas del proveedor.", "En tests, un fake implementa la misma interfaz sin hacer red."], ["No escondas diferencias semánticas importantes detrás de una interfaz falsa.", "Traducí también errores externos a errores propios que el service pueda manejar."], "Tu dominio habla su idioma; el adapter se ocupa del idioma del proveedor.", { prompt: "“Hoy se cobra con Stripe, pero el cliente quiere poder migrar o usar otro proveedor por país.”", diagramTitle: "Frontera externa", diagram: [{ label: "CheckoutOrder", detail: "caso de uso" }, { label: "PaymentGateway", detail: "interfaz propia" }, { label: "Adapter", detail: "traduce contrato" }, { label: "Stripe / Adyen", detail: "SDK externo" }] }),
  case_content: lesson("Caso de diseño", "Comentarios o adjuntos reutilizables pueden pertenecer a distintos modelos mediante una asociación polimórfica.", "Es el caso concreto que demuestra cuándo elegir polimorfismo y cuándo preferir asociaciones explícitas.", "class Comment < ApplicationRecord\n  belongs_to :commentable, polymorphic: true\nend\n\nclass Post < ApplicationRecord\n  has_many :comments, as: :commentable\nend\n\nclass Video < ApplicationRecord\n  has_many :comments, as: :commentable\nend", "Un comportamiento transversal", ["comments guarda commentable_type y commentable_id.", "Agregar un nuevo commentable no requiere otra foreign key nullable.", "El service de creación autoriza el recurso concreto antes de crear el comentario."], ["La base no puede imponer una foreign key tradicional hacia varias tablas.", "Consultas globales y renombrar clases requieren cuidado por guardar el nombre del tipo."], "Elegí polimorfismo cuando la capacidad es verdaderamente transversal y aceptás menor integridad referencial.", { prompt: "“Posts, videos y tickets deben aceptar comentarios con la misma funcionalidad.”", diagramTitle: "Asociación polimórfica", diagram: [{ label: "Comment", detail: "body + author" }, { label: "commentable", detail: "type + id" }, { label: "Post", detail: "un tipo posible" }, { label: "Video / Ticket", detail: "otros tipos" }] }),
  serialization_cors: lesson("API para React", "Una API debe controlar su representación JSON y permitir explícitamente los orígenes que pueden llamarla desde el navegador.", "React y Rails separados convierten serialización y CORS en parte del contrato, no en detalles accidentales.", "render json: OrderSerializer.new(order), status: :ok\n\n# config/initializers/cors.rb\nRails.application.config.middleware.insert_before 0, Rack::Cors do\n  allow do\n    origins \"https://app.example.com\"\n    resource \"/api/*\", headers: :any, methods: %i[get post patch delete options]\n  end\nend", "Contrato frontend/backend", ["Un serializer decide campos, nombres y relaciones expuestas.", "CORS es una política del navegador y debe listar orígenes y métodos permitidos.", "Versioná cambios incompatibles o coordiná el contrato con el frontend."], ["CORS no autentica ni autoriza usuarios.", "Renderizar modelos completos puede filtrar columnas internas o causar N+1."], "Para React, JSON es una interfaz pública: explícita, pequeña, estable y autorizada."),
  auth_security: lesson("API y seguridad", "Autenticación responde quién es el usuario; autorización decide si puede ejecutar una acción sobre un recurso.", "En Rails web aparecen además sesiones, cookies firmadas, CSRF y strong params como defensas comunes.", "class OrdersController < ApplicationController\n  before_action :authenticate_user!\n\n  def show\n    order = current_user.orders.find(params[:id])\n    render json: OrderSerializer.new(order)\n  end\nend\n\n# Buscar a través de current_user evita exponer órdenes ajenas.", "Autenticar y limitar alcance", ["Sesiones/cookies son comunes en Rails server-rendered; tokens suelen aparecer en APIs separadas.", "CSRF protege requests autenticadas por cookie; CORS resuelve otro problema.", "La autorización puede ser explícita o usar una policy como Pundit."], ["Estar autenticado no implica poder acceder a cualquier id.", "Nunca confíes en user_id enviado por el cliente si podés derivarlo de current_user."], "Seguridad se diseña por request: identidad, permiso, entrada permitida y salida mínima."),
  asset_pipeline: lesson("Tema explícito de entrevista", "El asset pipeline clásico recopila, procesa y publica CSS, JavaScript e imágenes con nombres fingerprinted.", "Te lo mencionaron directamente; esperan que puedas explicar Sprockets, precompilación, cache y por qué existe.", "// app/assets/config/manifest.js\n//= link_tree ../images\n//= link_directory ../stylesheets .css\n\n# Producción\nrails assets:precompile\n\n# application.css\n# -> application-a1b2c3d4.css", "Del fuente al asset cacheable", ["Sprockets busca assets en load paths y genera una salida compilada.", "El fingerprint cambia con el contenido, permitiendo Cache-Control largo sin servir una versión vieja.", "El manifest conecta el nombre lógico usado por helpers con el archivo generado."], ["Un asset ausente en producción suele indicar manifest, precompile o referencia incorrecta.", "Asset pipeline no es lo mismo que un bundler moderno de módulos JavaScript."], "Explicación corta: procesamiento + manifest + fingerprint + cache busting durante deploy."),
  modern_assets: lesson("Tema explícito de entrevista", "Rails pasó de Sprockets para todo, a Webpacker, y luego a opciones más pequeñas como importmap-rails, jsbundling-rails y cssbundling-rails.", "Mostrar la evolución importa más que memorizar una versión: cada proyecto Rails puede tener una generación distinta.", "Sprockets       # assets clásicos\nWebpacker       # integración histórica de Webpack\nimportmap-rails # módulos sin bundling\njsbundling-rails # esbuild / rollup / webpack\n\n# React separado:\n# Rails API sirve JSON y el frontend tiene su build propio.", "Elegir según la arquitectura", ["Webpacker permitió npm y módulos modernos dentro de Rails, pero sumó configuración y fue retirado.", "Import maps simplifica apps sin necesidades de bundling complejas.", "Para React separado, el pipeline del frontend suele vivir fuera de Rails."], ["No asumas la estrategia: preguntá qué versión de Rails y cómo se despliega React.", "La evolución histórica no significa que debas migrar una app estable sin una razón."], "Respuesta senior: identifico la generación del proyecto, sus necesidades y quién posee el build."),
  ruby_basics: lesson("Punto de partida", "No necesitás aprender Ruby entero antes de Rails: necesitás reconocer la sintaxis que aparece en modelos, controllers y ejemplos.", "Tu conocimiento backend ya transfiere; este nodo solo evita que la sintaxis de Ruby te tape el concepto Rails que estás estudiando.", "# símbolo, hash y keyword arguments\ndef create_order(user:, status: :pending)\n  { user_id: user.id, status: status }\nend\n\n# bloque: equivalente a recorrer una colección\nposts.each do |post|\n  puts post.title\nend\n\norder.save! # ! suele indicar que lanza excepción si falla", "El Ruby que vas a encontrar en Rails", ["Los símbolos como :pending son valores livianos y se usan mucho como nombres, estados y keys.", "{ name: \"Ana\" } es un Hash; Rails usa hashes para params, opciones y condiciones de queries.", "Los keyword arguments user: y status: hacen explícitas las dependencias o datos de entrada.", "do ... end delimita un bloque, parecido a una función anónima que recibe un método como each, transaction o scope.", "El sufijo ! es una convención, no magia universal: en Rails suele significar una versión más estricta que puede lanzar excepción."], ["No confundas :symbol con un String; ambos pueden representar texto, pero Rails usa símbolos para muchas APIs internas.", "No intentes traducir cada línea de Ruby a PHP antes de entender la intención del ejemplo: primero identificá modelo, operación y resultado."], "Si podés leer símbolos, hashes, keyword args, bloques y el !, los ejemplos Rails dejan de parecer otro idioma."),
  env_logger: lesson("Runtime Rails", "ENV/Credentials separan configuración del código y Rails.logger deja evidencia operacional con contexto.", "Son equivalentes directos de Dotenv y Monolog, por lo que deberías poder explicarlos rápidamente en lenguaje Rails.", "database_url = ENV.fetch(\"DATABASE_URL\")\nstripe_key = Rails.application.credentials.dig(:stripe, :secret_key)\n\nRails.logger.info(\n  \"checkout_started\",\n  order_id: order.id,\n  user_id: order.user_id\n)", "Configuración y observabilidad", ["ENV.fetch falla temprano si falta configuración obligatoria.", "Credentials almacena secretos cifrados; la clave de descifrado se gestiona fuera del repo.", "Los logs deben incluir IDs y etapa, no passwords, tokens ni datos sensibles."], ["No expongas variables privadas al bundle React.", "Loguear demasiado ruido puede ocultar el evento que necesitás diagnosticar."], "Configuración explícita y logs contextualizados son parte del diseño, no detalles de deploy."),
};

export default LESSONS;
